import os
from datetime import datetime, timedelta
from airflow import Dataset
from airflow.decorators import dag
from airflow.operators.empty import EmptyOperator
from airflow.providers.google.cloud.transfers.mysql_to_gcs import MySQLToGCSOperator
from airflow.providers.google.cloud.transfers.gcs_to_bigquery import GCSToBigQueryOperator
default_args = {'owner': 'aloisio lemos', 'retries': 1, 'retry_delay': timedelta(minutes=5)}
gcp_bucket_airflow = 'demo-airflow-data-bucket'

@dag(dag_id='demo_mysql_nps_parallel', start_date=datetime(2025, 2, 1), schedule=None, max_active_runs=1, default_args=default_args, catchup=False, tags=['NPS', 'BIGQUERY', 'daily', 'development', 'ingestion', 'MySQL', 'Google'], is_paused_upon_creation=True)
def ingest_data():
    init = EmptyOperator(task_id='init')
    campaign_mysql_to_gcs = MySQLToGCSOperator(task_id='campaign_mysql_to_gcs', mysql_conn_id='demo_mysql', sql='\n            SELECT id, status, code, name, tags, organization_id,\n                   create_time, \n                   update_time, \n                   campaign_key \n            FROM common.campaign\n        ', bucket=gcp_bucket_airflow, filename='data/nps_tabelas_json/campaign.json', export_format='json', gzip=True)
    campaign_campaign_group_mysql_to_gcs = MySQLToGCSOperator(task_id='campaign_campaign_group_mysql_to_gcs', mysql_conn_id='demo_mysql', sql='\n            SELECT id, campaign_id, campaign_group_id, \n                   create_time, \n                   update_time\n            FROM common.campaign_campaign_group\n        ', bucket=gcp_bucket_airflow, filename='data/nps_tabelas_json/campaign_campaign_group.json', export_format='json', gzip=True)
    campaign_group_mysql_to_gcs = MySQLToGCSOperator(task_id='campaign_group_mysql_to_gcs', mysql_conn_id='demo_mysql', sql='\n            SELECT id, name, organization_id,\n                   create_time,\n                   update_time\n            FROM common.campaign_group\n        ', bucket=gcp_bucket_airflow, filename='data/nps_tabelas_json/campaign_group.json', export_format='json', gzip=True)
    survey_mysql_to_gcs = MySQLToGCSOperator(task_id='survey_mysql_to_gcs', mysql_conn_id='demo_mysql', sql='\n            SELECT id,campaign_id,\n                create_time, \n                update_time, \n                delete_time \n            from common.survey\n        ', bucket=gcp_bucket_airflow, filename='data/nps_tabelas_json/survey.json', export_format='json', gzip=True)
    question_mysql_to_gcs = MySQLToGCSOperator(task_id='question_mysql_to_gcs', mysql_conn_id='demo_mysql', sql='\n            SELECT id,survey_id,status,type,title,question,\n                create_time, \n                update_time, \n                delete_time  \n            from common.question\n        ', bucket=gcp_bucket_airflow, filename='data/nps_tabelas_json/question.json', export_format='json', gzip=True)
    question_answer_mysql_to_gcs = MySQLToGCSOperator(task_id='question_answer_mysql_to_gcs', mysql_conn_id='demo_mysql', sql="\n            SELECT id,question_id,type, \n            status,\n            create_time,\n            update_time,\n            organization_id,\n            campaign_id from question_answer\n            WHERE FROM_UNIXTIME(create_time) BETWEEN '2024-01-01' AND '2025-02-11'\n        ", bucket=gcp_bucket_airflow, filename='data/nps_tabelas_json/question_answer.json', export_format='json', gzip=True)
    question_answer_nps_mysql_to_gcs = MySQLToGCSOperator(task_id='question_answer_nps_mysql_to_gcs', mysql_conn_id='demo_mysql', sql="\n            SELECT \n                id, \n                question_answer_id,\n                status, \n                nps_comment, \n                nps_answer,\n                last_nps_answer, \n                create_time,\n                update_time\n            FROM \n                common.question_answer_nps\n            WHERE FROM_UNIXTIME(create_time) BETWEEN '2024-01-01' AND '2025-02-11'\n        ", bucket=gcp_bucket_airflow, filename='data/nps_tabelas_json/question_answer_nps.json', export_format='json', gzip=True)
    load_campain_data_to_bq = GCSToBigQueryOperator(task_id='load_campain_data_to_bq', bucket=gcp_bucket_airflow, source_objects=['data/nps_tabelas_json/campaign.json'], destination_project_dataset_table='demo-project.analytics.campaign', source_format='NEWLINE_DELIMITED_JSON', write_disposition='WRITE_APPEND', create_disposition='CREATE_IF_NEEDED', schema_fields=[{'name': 'id', 'type': 'INTEGER', 'mode': 'NULLABLE'}, {'name': 'status', 'type': 'INTEGER', 'mode': 'NULLABLE'}, {'name': 'code', 'type': 'STRING', 'mode': 'NULLABLE'}, {'name': 'name', 'type': 'STRING', 'mode': 'NULLABLE'}, {'name': 'tags', 'type': 'STRING', 'mode': 'NULLABLE'}, {'name': 'organization_id', 'type': 'INTEGER', 'mode': 'NULLABLE'}, {'name': 'create_time', 'type': 'TIMESTAMP', 'mode': 'NULLABLE'}, {'name': 'update_time', 'type': 'TIMESTAMP', 'mode': 'NULLABLE'}, {'name': 'campaign_key', 'type': 'STRING', 'mode': 'NULLABLE'}])
    load_campaign_campaign_group_to_bq = GCSToBigQueryOperator(task_id='load_campaign_campaign_group_to_bq', bucket=gcp_bucket_airflow, source_objects=['data/nps_tabelas_json/campaign_campaign_group.json'], destination_project_dataset_table='demo-project.analytics.campaign_campaign_group', source_format='NEWLINE_DELIMITED_JSON', write_disposition='WRITE_APPEND', create_disposition='CREATE_IF_NEEDED', schema_fields=[{'name': 'id', 'type': 'INTEGER', 'mode': 'NULLABLE'}, {'name': 'campaign_id', 'type': 'INTEGER', 'mode': 'NULLABLE'}, {'name': 'campaign_group_id', 'type': 'INTEGER', 'mode': 'NULLABLE'}, {'name': 'create_time', 'type': 'TIMESTAMP', 'mode': 'NULLABLE'}, {'name': 'update_time', 'type': 'TIMESTAMP', 'mode': 'NULLABLE'}])
    load_campaign_group_to_bq = GCSToBigQueryOperator(task_id='load_campaign_group_to_bq', bucket=gcp_bucket_airflow, source_objects=['data/nps_tabelas_json/campaign_group.json'], destination_project_dataset_table='demo-project.analytics.campaign_group', source_format='NEWLINE_DELIMITED_JSON', write_disposition='WRITE_APPEND', create_disposition='CREATE_IF_NEEDED', schema_fields=[{'name': 'id', 'type': 'INTEGER', 'mode': 'NULLABLE'}, {'name': 'name', 'type': 'STRING', 'mode': 'NULLABLE'}, {'name': 'organization_id', 'type': 'INTEGER', 'mode': 'NULLABLE'}, {'name': 'create_time', 'type': 'TIMESTAMP', 'mode': 'NULLABLE'}, {'name': 'update_time', 'type': 'TIMESTAMP', 'mode': 'NULLABLE'}])
    load_survey_to_bq = GCSToBigQueryOperator(task_id='load_survey_to_bq', bucket=gcp_bucket_airflow, source_objects=['data/nps_tabelas_json/survey.json'], destination_project_dataset_table='demo-project.analytics.survey', source_format='NEWLINE_DELIMITED_JSON', write_disposition='WRITE_APPEND', create_disposition='CREATE_IF_NEEDED', schema_fields=[{'name': 'id', 'type': 'INTEGER', 'mode': 'NULLABLE'}, {'name': 'campaign_id', 'type': 'INTEGER', 'mode': 'NULLABLE'}, {'name': 'create_time', 'type': 'TIMESTAMP', 'mode': 'NULLABLE'}, {'name': 'update_time', 'type': 'TIMESTAMP', 'mode': 'NULLABLE'}, {'name': 'delete_time', 'type': 'TIMESTAMP', 'mode': 'NULLABLE'}])
    load_question_to_bq = GCSToBigQueryOperator(task_id='load_question_to_bq', bucket=gcp_bucket_airflow, source_objects=['data/nps_tabelas_json/question.json'], destination_project_dataset_table='demo-project.analytics.question', source_format='NEWLINE_DELIMITED_JSON', write_disposition='WRITE_APPEND', create_disposition='CREATE_IF_NEEDED', schema_fields=[{'name': 'id', 'type': 'INTEGER', 'mode': 'NULLABLE'}, {'name': 'survey_id', 'type': 'INTEGER', 'mode': 'NULLABLE'}, {'name': 'status', 'type': 'INTEGER', 'mode': 'NULLABLE'}, {'name': 'type', 'type': 'INTEGER', 'mode': 'NULLABLE'}, {'name': 'title', 'type': 'STRING', 'mode': 'NULLABLE'}, {'name': 'question', 'type': 'STRING', 'mode': 'NULLABLE'}, {'name': 'create_time', 'type': 'TIMESTAMP', 'mode': 'NULLABLE'}, {'name': 'update_time', 'type': 'TIMESTAMP', 'mode': 'NULLABLE'}, {'name': 'delete_time', 'type': 'TIMESTAMP', 'mode': 'NULLABLE'}])
    load_question_answer_to_bq = GCSToBigQueryOperator(task_id='load_question_answer_to_bq', bucket=gcp_bucket_airflow, source_objects=['data/nps_tabelas_json/question_answer.json'], destination_project_dataset_table='demo-project.analytics.question_answer', source_format='NEWLINE_DELIMITED_JSON', write_disposition='WRITE_APPEND', create_disposition='CREATE_IF_NEEDED', schema_fields=[{'name': 'id', 'type': 'INTEGER', 'mode': 'NULLABLE'}, {'name': 'question_id', 'type': 'INTEGER', 'mode': 'NULLABLE'}, {'name': 'organization_id', 'type': 'INTEGER', 'mode': 'NULLABLE'}, {'name': 'campaign_id', 'type': 'INTEGER', 'mode': 'NULLABLE'}, {'name': 'status', 'type': 'INTEGER', 'mode': 'NULLABLE'}, {'name': 'type', 'type': 'INTEGER', 'mode': 'NULLABLE'}, {'name': 'create_time', 'type': 'TIMESTAMP', 'mode': 'NULLABLE'}, {'name': 'update_time', 'type': 'TIMESTAMP', 'mode': 'NULLABLE'}])
    load_question_answer_nps_to_bq = GCSToBigQueryOperator(task_id='load_question_answer_nps_to_bq', bucket=gcp_bucket_airflow, source_objects=['data/nps_tabelas_json/question_answer_nps.json'], destination_project_dataset_table='demo-project.analytics.question_answer_nps', source_format='NEWLINE_DELIMITED_JSON', write_disposition='WRITE_APPEND', create_disposition='CREATE_IF_NEEDED', schema_fields=[{'name': 'id', 'type': 'INTEGER', 'mode': 'NULLABLE'}, {'name': 'question_answer_id', 'type': 'INTEGER', 'mode': 'NULLABLE'}, {'name': 'status', 'type': 'INTEGER', 'mode': 'NULLABLE'}, {'name': 'nps_comment', 'type': 'STRING', 'mode': 'NULLABLE'}, {'name': 'nps_answer', 'type': 'INTEGER', 'mode': 'NULLABLE'}, {'name': 'last_nps_answer', 'type': 'INTEGER', 'mode': 'NULLABLE'}, {'name': 'create_time', 'type': 'TIMESTAMP', 'mode': 'NULLABLE'}, {'name': 'update_time', 'type': 'TIMESTAMP', 'mode': 'NULLABLE'}])
    finish = EmptyOperator(task_id='finish')
    init >> [campaign_mysql_to_gcs, campaign_campaign_group_mysql_to_gcs, campaign_group_mysql_to_gcs, survey_mysql_to_gcs, question_mysql_to_gcs, question_answer_mysql_to_gcs, question_answer_nps_mysql_to_gcs]
    campaign_mysql_to_gcs >> load_campain_data_to_bq
    campaign_campaign_group_mysql_to_gcs >> load_campaign_campaign_group_to_bq
    campaign_group_mysql_to_gcs >> load_campaign_group_to_bq
    survey_mysql_to_gcs >> load_survey_to_bq
    question_mysql_to_gcs >> load_question_to_bq
    question_answer_mysql_to_gcs >> load_question_answer_to_bq
    question_answer_nps_mysql_to_gcs >> load_question_answer_nps_to_bq
    [load_campain_data_to_bq, load_campaign_campaign_group_to_bq, load_campaign_group_to_bq, load_survey_to_bq, load_question_to_bq, load_question_answer_to_bq, load_question_answer_nps_to_bq] >> finish
ingest_data()
